#include "evengine/platform.hpp"
#include "evengine/studio.hpp"
#include <SDL3/SDL.h>
#include <iostream>
using namespace evengine;
int main(int argc,char**argv){try{StudioGame game(argv[1]);auto platform=createPlatform(game.atlas,"RC input validation");platform->configureInput(game.keyBindings,game.buttonBindings);Input input;int checks=0;auto check=[&](bool ok,const char* message){if(!ok)throw std::runtime_error(std::string(message)+": "+SDL_GetError());++checks;std::cout<<"OK "<<message<<'\n';};auto key=[&](SDL_Scancode code){input=Input{};SDL_Event event{};event.type=SDL_EVENT_KEY_DOWN;event.key.scancode=code;event.key.down=true;check(SDL_PushEvent(&event),"keyboard event submitted");platform->poll(input);};key(SDL_SCANCODE_E);check(input.hit(Action::Interact)&&platform->takeKeyPress()=="E","default named action and raw key capture agree");game.keyBindings[Action::Interact]="T";platform->configureInput(game.keyBindings,game.buttonBindings);key(SDL_SCANCODE_E);check(!input.hit(Action::Interact),"rebound action releases old key");key(SDL_SCANCODE_T);check(input.hit(Action::Interact),"rebound key invokes action");key(SDL_SCANCODE_RETURN);check(input.hit(Action::Interact),"Enter remains a menu fallback");key(SDL_SCANCODE_ESCAPE);check(input.hit(Action::Pause)&&!input.hit(Action::Quit),"Escape maps to pause");
SDL_VirtualJoystickDesc desc;SDL_INIT_INTERFACE(&desc);desc.type=SDL_JOYSTICK_TYPE_GAMEPAD;desc.name="RC virtual controller";desc.naxes=SDL_GAMEPAD_AXIS_COUNT;desc.nbuttons=SDL_GAMEPAD_BUTTON_COUNT;desc.axis_mask=(1u<<SDL_GAMEPAD_AXIS_COUNT)-1;desc.button_mask=(1u<<SDL_GAMEPAD_BUTTON_COUNT)-1;auto id=SDL_AttachVirtualJoystick(&desc);check(id!=0,"virtual gamepad attaches");auto stick=SDL_OpenJoystick(id);check(stick!=nullptr,"virtual gamepad opens");platform->poll(input);auto button=[&](int code,bool down){SDL_SetJoystickVirtualButton(stick,code,down);SDL_UpdateJoysticks();platform->poll(input);};input=Input{};button(SDL_GAMEPAD_BUTTON_SOUTH,true);check(input.hit(Action::Interact)&&platform->usingGamepad(),"controller confirm action and prompt mode update");button(SDL_GAMEPAD_BUTTON_SOUTH,false);input.consume();button(SDL_GAMEPAD_BUTTON_START,true);check(input.hit(Action::Pause),"controller Start pauses");button(SDL_GAMEPAD_BUTTON_START,false);input.consume();button(SDL_GAMEPAD_BUTTON_NORTH,true);check(input.hit(Action::Journal)&&!input.hit(Action::Run),"controller journal does not also run");button(SDL_GAMEPAD_BUTTON_NORTH,false);input.consume();SDL_SetJoystickVirtualAxis(stick,SDL_GAMEPAD_AXIS_LEFTX,24000);SDL_UpdateJoysticks();platform->poll(input);check(input.down(Action::Right),"analog stick uses directional action");SDL_SetJoystickVirtualAxis(stick,SDL_GAMEPAD_AXIS_LEFTX,0);SDL_UpdateJoysticks();platform->poll(input);game.buttonBindings[Action::Interact]="east";game.buttonBindings[Action::Attack]="south";platform->configureInput(game.keyBindings,game.buttonBindings);input=Input{};button(SDL_GAMEPAD_BUTTON_EAST,true);check(input.hit(Action::Interact)&&!input.hit(Action::Attack),"custom gamepad binding replaces default");button(SDL_GAMEPAD_BUTTON_EAST,false);key(SDL_SCANCODE_T);check(!platform->usingGamepad(),"keyboard input restores keyboard prompt mode");SDL_CloseJoystick(stick);SDL_DetachVirtualJoystick(id);platform->poll(input);check(!input.down(Action::Right)&&!input.down(Action::Interact),"controller removal clears held actions");platform->confirmWindowClose(true);SDL_Event closing{};closing.type=SDL_EVENT_WINDOW_CLOSE_REQUESTED;SDL_PushEvent(&closing);check(platform->poll(input)&&platform->takeCloseRequest(),"window close is delivered without terminating the platform");check(!platform->takeCloseRequest(),"window close request is consumed once");closing.type=SDL_EVENT_QUIT;SDL_PushEvent(&closing);check(platform->poll(input)&&platform->takeCloseRequest(),"application quit also requests confirmation");platform->confirmWindowClose(false);SDL_PushEvent(&closing);check(!platform->poll(input),"legacy platform clients retain immediate close behavior");std::cout<<checks<<" SDL input checks passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
